    return VerifyTableStart(verifier) &&
           VerifyField<uint16_t>(verifier, VT_TILE_INDEX, 2) &&
           VerifyField<uint32_t>(verifier, VT_TYPE, 4) &&
           VerifyField<uint8_t>(verifier, VT_INTENSITY, 1) &&
           verifier.EndTable();
