  std::vector<std::unique_ptr<cdda::ipc::EntityT>> entity_updates{};
  std::vector<uint64_t> entity_removed{};
  std::vector<std::unique_ptr<cdda::ipc::VehicleT>> vehicle_updates{};
  std::vector<uint64_t> vehicle_removed{};
