inline bool VerifyMessage(::flatbuffers::Verifier &verifier, const void *obj, Message type) {
  switch (type) {
    case Message_NONE: {
      return true;
    }
    case Message_Hello: {
      auto ptr = reinterpret_cast<const cdda::ipc::Hello *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Message_HelloAck: {
      auto ptr = reinterpret_cast<const cdda::ipc::HelloAck *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Message_TileDefs: {
      auto ptr = reinterpret_cast<const cdda::ipc::TileDefs *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Message_Snapshot: {
      auto ptr = reinterpret_cast<const cdda::ipc::Snapshot *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Message_Delta: {
      auto ptr = reinterpret_cast<const cdda::ipc::Delta *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Message_LightUpdate: {
      auto ptr = reinterpret_cast<const cdda::ipc::LightUpdate *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Message_Effects: {
      auto ptr = reinterpret_cast<const cdda::ipc::Effects *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Message_UiFrame: {
      auto ptr = reinterpret_cast<const cdda::ipc::UiFrame *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Message_Input: {
      auto ptr = reinterpret_cast<const cdda::ipc::Input *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Message_Resize: {
      auto ptr = reinterpret_cast<const cdda::ipc::Resize *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Message_PickResult: {
      auto ptr = reinterpret_cast<const cdda::ipc::PickResult *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Message_Ping: {
      auto ptr = reinterpret_cast<const cdda::ipc::Ping *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Message_Pong: {
      auto ptr = reinterpret_cast<const cdda::ipc::Pong *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Message_Shutdown: {
      auto ptr = reinterpret_cast<const cdda::ipc::Shutdown *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Message_EnvironmentUpdate: {
      auto ptr = reinterpret_cast<const cdda::ipc::EnvironmentUpdate *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifyMessageVector(::flatbuffers::Verifier &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyMessage(
        verifier,  values->Get(i), types->GetEnum<Message>(i))) {
      return false;
    }
  }
  return true;
}

